-- 014_expert_catalog.sql — curated AI expert catalog rows (BIGINT id table).
-- Experts are storefront curated presentation content carried by the
-- app-template platform with template_type = 'EXPERT'
-- (specs/AGENTS_DEPENDENCY_BOUNDARY_SPEC.md section 4): not an Agents
-- contract, never written into Agents tables. template_platform stays NULL —
-- the platform dimension describes the application form a scaffold produces,
-- which an expert does not have. Category rows for the experts page (场景
-- cards) are derived at read time by grouping these rows on category_code, so
-- the card counts and featured experts always match the stored catalog.

ON CONFLICT (id) DO NOTHING;

-- Backfill the icon resource for rows planted by earlier seed runs (the
-- INSERT above skips them on conflict).
UPDATE appstore_app_template
SET icon_media_resource_id = 'mr-' || template_code || '-icon'
WHERE tenant_id = 100001
  AND template_type = 'EXPERT'
  AND (icon_media_resource_id IS NULL OR icon_media_resource_id = '');

UPDATE appstore_app_template
SET metadata = metadata || jsonb_build_object('avatarIcon', COALESCE(metadata->>'avatarIcon', 'Bot'))
WHERE tenant_id = 100001
  AND template_type = 'EXPERT'
  AND COALESCE(metadata->>'avatarIcon', '') = '';
