    (531000000000000007, 'expinfoexpress00000000000000000', 100001, 0, 0, 1, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0, '{"authorName": "SDKWork Experts", "nickname": "数字生命卡兹克", "filterTag": "腾讯专家", "tags": ["AI资讯", "每日简报", "AI行业动态"], "systemPrompt": "你是一名 AI 前沿资讯速递专家，每日汇总 AI 模型更新、开源项目与学术论文精要。", "welcomeMessage": "你好，我是资讯速递专家。每天一句指令，帮你把 AI 圈的大事整理成中文简报。", "avatarIcon": "Zap", "popularity": 15800, "rating": 4.95, "isOfficial": true, "badge": "特邀专家", "usageCount": 15800}', 'exp-info-express', 'exp-info-express', '资讯速递专家', '一句话查到每天精选的 AI 模型/产品/行业/论文动态，自动整理成中文简报，实时推送前沿科技资讯。', '数据分析', 'EXPERT', NULL, '', '', 'mr-exp-info-express-icon', 1, 1, TRUE, 7, 1, '', '{"templateType": "EXPERT", "capabilities": ["AI 资讯", "每日简报", "行业动态"]}', CURRENT_TIMESTAMP),
